import './controls.js';
import {mascot} from './mascot.js';
import {escape as E,markdown,answerMarkup} from './markdown.js';
const root=document.querySelector('#app'),modal=document.querySelector('#modal'),modalBody=document.querySelector('#modal-body');
let state={},cid=null,conversation={messages:[],nodes:[],wiki:[]},busy=false,diagram=false,images=[],sources=[],selected=new Set(),clock;
const reveals=new Map();const fox=mascot();let draft='',mode='research',settingsTab=null,editingProvider=null,settingsDraft=null;
const icon=name=>'<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+({left:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16"/>',right:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M15 4v16"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11H3Z"/><path d="M3 10h18"/>',settings:'<path d="m9 4 1-2h4l1 2 3 2 2 1v4l-2 1-2 4-1 3h-5l-1-3-3-2-2-1V9l2-1Z"/><circle cx="12" cy="10" r="3"/>'}[name]||'<path d="M12 4v16M4 12h16"/>')+'</svg>';
function fitInput(){const el=document.querySelector('#prompt');if(!el)return;el.style.height='0px';el.style.height=Math.min(240,Math.max(42,el.scrollHeight))+'px';el.style.overflowY=el.scrollHeight>240?'auto':'hidden';}
function emptyChat(){return conversation.messages.length===0;}
async function projectDialog(){const result=state.project?await call('projectFiles'):null;showModal(`<span class="eyebrow">LOCAL WORKSPACE</span><h2>專案與檔案</h2><p>${result?E(result.root):'選擇電腦上的資料夾，或建立新的專案。'}</p><div class="settings-actions"><button data-act="project">開啟資料夾</button><button data-act="general-chat">一般聊天</button><button data-act="new-project">建立專案</button>${result?'<button data-act="open-project" data-editor="true">Open in VS Code ↗</button><button data-act="open-project">Open in File Explorer ↗</button><button data-act="new-file">新增檔案</button><button data-act="new-folder">新增資料夾</button>':''}</div>${result?`<div class="file-list">${result.files.map(f=>f.directory?`<div class="hint">▱ ${E(f.path)}</div>`:`<button data-act="edit-file" data-path="${E(f.path)}"><span>${E(f.path)}</span><small>${Math.ceil(f.size/1024)} KB</small></button>`).join('')||'<p>這個專案還沒有檔案。</p>'}</div><p class="hint">點擊檔案可直接編輯。儲存前會確認，並記錄到 CodeWiki；專案內容只有在程式模式中才會傳給模型。</p>`:''}`);}
function fileEditor(file={path:'',text:''}){showModal(`<span class="eyebrow">LOCAL FILE EDITOR</span><h2>${file.path?'編輯檔案':'新增檔案'}</h2><label>專案內的相對路徑<input id="file-path" value="${E(file.path)}" ${file.path?'readonly':''} placeholder="src/index.js"></label><textarea class="file-editor" id="file-text" spellcheck="false" maxlength="60000">${E(file.text)}</textarea><div class="settings-actions"><button class="primary" data-act="save-file">儲存至電腦</button><button data-act="project-panel">返回專案</button></div>`);}
function panels(){const app=document.querySelector('.app-shell');if(app){app.classList.toggle('left-collapsed',!!state.settings.leftCollapsed);app.classList.toggle('right-collapsed',!!state.settings.rightCollapsed);}document.querySelectorAll('[data-act=toggle-left]').forEach(b=>b.setAttribute('aria-expanded',String(!state.settings.leftCollapsed)));document.querySelectorAll('[data-act=toggle-right]').forEach(b=>b.setAttribute('aria-expanded',String(!state.settings.rightCollapsed)));}
function settingsNav(tab){settingsDraft||={appearance:{...state.settings},niv:structuredClone(state.niv),nivChanged:false,removeProviders:[]};settingsTab=tab;return `<nav class="settings-nav" aria-label="設定分類">${[['appearance','外觀'],['providers','模型'],['search','Search'],['usage','Usage'],['niv','記憶'],['account','帳戶與說明']].map(([id,label])=>`<button data-act="settings-tab" data-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</nav>`;}
function settingsDialog(tab='appearance'){if(tab==='search')searchDialog();else if(tab==='usage')usageDialog();else if(tab==='providers')providersDialog();else if(tab==='niv')nivDialog();else if(tab==='account')showModal(settingsNav(tab)+`<h2>Account & support.</h2><p>${E(state.user?.email||'')}</p><div class="settings-actions"><button data-act="manual">使用手冊 ↗</button><button data-act="feedback">提交回饋 ↗</button><button data-act="snaps">我的 Snap</button><button data-act="remote">Remote tasks · 72h</button><button data-act="privacy-settings">Language & privacy</button><button data-act="logout">登出</button></div><p class="hint">Naivi — A Cygnus Automation Project<br>By SanGuai Culture Studio / SanGuai Inc. HK</p>`);else appearanceDialog();}
function appearanceDialog(){settingsNav('appearance');const s=settingsDraft.appearance;showModal(settingsNav('appearance')+`${languageControl()}<span class="eyebrow">PERSONALIZE YOUR SPACE</span><h2>Less noise. More you.</h2><div class="row"><label>介面主題<select id="theme"><option value="dark">純黑 / Pure black</option><option value="light">紙白 / Paper</option><option value="system">跟隨系統</option></select></label><label>強調色<select id="accent"><option value="#ffffff">月白</option><option value="#99b8ff">霧藍</option><option value="#a8cfbd">鼠尾草</option><option value="#c4b5e5">暮紫</option><option value="#ddb98a">暖砂</option></select></label></div><div class="row"><label>英文字體<select id="font-en"><option value="serif">Georgia · 襯線</option><option value="sans">Inter · 無襯線</option><option value="mono">Consolas · 等寬</option></select></label><label>中文字體<select id="font-zh"><option value="sans">微軟正黑體 / 系統黑體</option><option value="serif">思源宋體 / 系統明體</option></select></label></div><label>閱讀字級 <output id="font-value">${s.fontSize||15}</output> px<input type="range" min="12" max="22" value="${s.fontSize||15}" id="font-size"></label><section class="reading-preview" aria-label="Reading preview"><span class="eyebrow">LIVE PREVIEW</span><p class="font-specimen" data-user-content>A quieter place to think.<br>把注意力留給真正重要的事。</p><p class="hint">Preview only. Changes apply after you save.</p></section><label class="switch-row"><input type="checkbox" id="show-agents" ${s.showAgents!==false?'checked':''}> Show agent companions</label><label class="switch-row"><input type="checkbox" id="effects" ${s.effects!==false?'checked':''}> 玻璃材質與動態效果</label><p class="hint">側欄折疊、訊息入場與協作球狀態使用動態過渡。遵循系統「減少動態效果」設定。</p><details class="css-editor"><summary>自訂整個應用程式的 CSS</summary><button data-act="css-manual">CSS 開發手冊 ↗</button><p class="hint">僅使用你信任的 CSS。若隱藏了設定入口，可按 Ctrl + Shift + Backspace 清除。</p><textarea id="app-css" spellcheck="false" maxlength="20000" placeholder=":root { --reading-size: 16px; }">${E(s.customCSS||'')}</textarea></details><label>Workspace layout<select id="layout"><option value="comfortable">Comfortable</option><option value="focus">Focused reading</option><option value="wide">Wide workspace</option></select></label><label>Output limit per model call<select id="limit-mode"><option value="unlimited">Unlimited by Naivi</option><option value="custom">Custom token limit</option></select></label><input id="output-limit" type="number" min="1" step="1" placeholder="4096"><p class="hint">Unlimited uses the provider default or its declared output capacity. Provider limits still apply. Incomplete output is saved so you can continue.</p><details><summary>進階模型設定</summary><label><input type="checkbox" id="same-model" ${s.allowSameModel?'checked':''}> 允許單模型角色測試（不是多模型驗證）</label></details><footer class="settings-save"><span>Changes apply only after saving.</span><button class="primary" data-act="save-appearance">儲存設定</button></footer>`);syncLanguage();document.querySelector('#language').value=s.language||'en';document.querySelector('#layout').value=s.layout||'comfortable';document.querySelector('#limit-mode').value=s.outputLimit?'custom':'unlimited';document.querySelector('#output-limit').value=s.outputLimit||'';document.querySelector('#theme').value=s.theme||'dark';document.querySelector('#accent').value=['#ffffff','#99b8ff','#a8cfbd','#c4b5e5','#ddb98a'].includes(s.accent)?s.accent:'#ffffff';document.querySelector('#font-en').value=s.fontEn||'serif';document.querySelector('#font-zh').value=s.fontZh||'sans';for(const id of ['font-size','font-en','font-zh'])document.getElementById(id).addEventListener('input',previewReading);previewReading();}
async function call(action,data){const r=await window.naivi.call(action,data);if(!r.ok)throw Error(r.error);return r.value;}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';if(el.matches(':popover-open'))el.hidePopover();el.showPopover?.();clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.hidePopover?.();el.style.display='none';},8000);}
function theme(){const settings=state.settings||{};setLanguage(settings.language);document.documentElement.dataset.layout=settings.layout||'comfortable';document.body.classList.toggle('hide-agents',settings.showAgents===false);const fonts={sans:'Inter',serif:'Georgia',mono:'Consolas'},zh={sans:'"Microsoft JhengHei","PingFang TC","Noto Sans TC"',serif:'"Noto Serif TC","PMingLiU"',mono:'"Microsoft JhengHei"'};document.documentElement.style.setProperty('--reading-font',`${fonts[settings.fontEn||'serif']},${zh[settings.fontZh||'sans']},sans-serif`);document.documentElement.style.setProperty('--reading-size',(settings.fontSize||15)+'px');document.documentElement.style.setProperty('--ui-size',Math.max(12,(settings.fontSize||15)-2)+'px');let css=document.querySelector('#user-styles');if(!css){css=document.createElement('style');css.id='user-styles';document.head.append(css);}css.textContent=settings.customCSS||'';document.documentElement.dataset.theme=settings.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):settings.theme||'dark';document.documentElement.style.setProperty('--accent',settings.accent||'#ffffff');const hex=(settings.accent||'#ffffff').slice(1);const rgb=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=0.04045?v/12.92:((v+0.055)/1.055)**2.4);document.documentElement.style.setProperty('--on-accent',rgb[0]*0.2126+rgb[1]*0.7152+rgb[2]*0.0722>0.179?'#111927':'#ffffff');document.body.classList.toggle('no-effects',settings.effects===false);}
function showModal(html){const isSettings=html.includes('class="settings-nav"');if(!isSettings)settingsDraft=null;modal.classList.toggle('settings-dialog',isSettings);modal.classList.remove('release-dialog');modalBody.innerHTML=html;modalBody.scrollTop=0;if(!modal.open)modal.showModal();}
document.querySelector('#close-modal').onclick=()=>modal.close();
modal.addEventListener('close',()=>{settingsDraft=null;settingsTab=null;});
function consent(){root.innerHTML=`<main class="overlay-stage"><section class="onboard"><div class="brand">Naivi.</div><h1>Your space.<br>Your choices.</h1>${languageControl()}<p>Choose your language and privacy preference. Local storage is required for settings and conversations. Naivi does not currently load advertising or analytics cookies.</p><div class="settings-actions"><button class="primary" data-act="consent">Necessary only</button><button data-act="consent" data-optional="true">Accept optional cookies</button></div></section></main>`;syncLanguage();}
function onboard(){root.innerHTML=`<main class="overlay-stage"><section class="onboard"><div class="brand">${fox} Naivi.</div>${languageControl()}<span class="eyebrow">A CYGNUS AUTOMATION PROJECT</span><h1>Intelligence<br>begins somewhere.</h1><p>由 SanGuai Culture Studio / SanGuai Inc. HK 開發。先花一點時間，了解你將使用的實驗平台。</p><button data-act="manual">閱讀 PHI 使用手冊 ↗</button><h3>使用聲明 · ${E(state.termsVersion)}</h3><div class="terms" tabindex="0"><ul><li>Naivi 是實驗性軟體。模型可能出錯、編造引用或產生不安全程式；多模型審查不保證正確，重要內容需人工查證。</li><li>你選取的訊息、來源、圖片及程式內容會傳送至你配置的模型服務或中轉站，受該服務政策及費用規則約束。請只提交有權使用的資料。</li><li>對話保存在本機；API Key 使用作業系統加密。共享電腦或已解鎖的帳戶不能視為機密保護邊界。</li><li>程式修改、測試執行、分享及銷毀需明確確認。回滾僅涵蓋已記錄檔案，無法撤銷所有外部副作用。</li><li>Snap 在建立後 24 小時到期，或由你提前銷毀；持有連結者可讀取，已被保存的副本無法收回。</li><li>請遵守適用法律與第三方權利。原始碼授權以隨附 LICENSE 為準；工作室名稱與標誌不因此授權冒用。</li></ul><p>詳情與現有網站政策請見 PHI 手冊。這些使用說明不影響依法不可排除的權利。</p></div><label><input type="checkbox" id="agree"> 我已閱讀手冊與使用聲明，了解上述限制並同意繼續。</label><button class="primary" data-act="accept">同意並登入 →</button></section></main>`;syncLanguage();}
function login(){root.innerHTML=`<main class="overlay-stage"><section class="onboard"><div class="brand">${fox} Naivi.</div>${languageControl()}<h2>Welcome to the lab.</h2><p>使用 Cygnus 帳戶登入。驗證碼由工作室網站郵件服務寄送。Niv 預設在本機自動記錄一般偏好，可隨時於設定關閉。</p><label>Email<input id="email" type="email" autocomplete="email" maxlength="254"></label><label>顯示名稱（首次登入）<input id="penName" maxlength="30" autocomplete="nickname"></label><div class="row"><button data-act="send-code">寄送驗證碼</button><input id="otp" placeholder="驗證碼" inputmode="numeric" autocomplete="one-time-code" maxlength="10"></div><p class="hint">請勿將驗證碼提供給模型。驗證碼不會進入對話。</p><button class="primary" data-act="login">驗證並登入 →</button><button data-act="guest">Continue without signing in →</button><p class="hint">Gmail sign-in is currently unavailable due to SMTP delivery limitations.</p><button data-act="manual">使用手冊</button></section></main>`;startCooldown(document.querySelector('[data-act=send-code]'));syncLanguage();}
function render(){const viewport=captureViewport(cid);const old=document.querySelector('#prompt');if(old){draft=old.value;mode=document.querySelector('#mode')?.value||mode;}theme();if(!state.settings.cookieChoice)return consent();if(!state.accepted)return onboard();if(!state.user)return login();root.innerHTML=`<div class="app-shell"><aside class="sidebar" aria-label="對話與專案"><div class="sidebar-top"><div class="brand">${fox}<span>Naivi.</span></div><button class="icon-button" data-act="toggle-left" title="折疊側邊欄" aria-label="折疊側邊欄">${icon('left')}</button></div><button class="new-chat" data-act="new" ${emptyChat()?'disabled':''} title="目前對話為空時不建立新對話"><span>＋</span><span class="label">新對話</span><kbd>Ctrl N</kbd></button><button class="project-nav" data-act="project-panel" title="專案與檔案"><span>${icon('folder')}</span><span class="label">專案與檔案</span></button><div class="sidebar-section">RECENT CONVERSATIONS</div><div class="conversations">${state.conversations.map(c=>`<button class="conversation ${c.id===cid?'active':''}" data-act="load" data-id="${E(c.id)}">${c.projectRoot?'▱ ':''}${E(c.title)}</button>`).join('')}</div><div class="side-bottom"><button data-act="feedback" title="回饋"><span>↗</span><span class="label">回饋與建議</span></button><button data-act="settings" title="設定"><span>${icon('settings')}</span><span class="label">設定</span></button><div class="user-label"><span class="avatar">${E((state.user.penName||'N')[0])}</span><span>${E(state.user.penName||'Naivi user')}<small>Personal workspace</small></span></div></div></aside><main class="workspace"><header class="topbar"><button class="icon-button reopen-left" data-act="toggle-left" aria-label="展開對話欄">${icon('left')}</button><div class="workspace-title">Phiel <span>DEMO</span><small>${state.project?E(state.project.root.split(/[\\/]/).pop()):'Personal workspace'}</small></div><div class="top-actions"><button data-act="wiki" title="CodeWiki">CodeWiki</button><button data-act="share" title="分享選取訊息">分享 ↗</button><button data-act="chat-menu" class="icon-button" aria-label="對話選項">···</button><button data-act="toggle-right" class="icon-button" title="顯示或折疊協作欄" aria-label="顯示或折疊協作欄">${icon('right')}</button></div></header><div class="messages" id="messages"></div><div class="composer-area"><div class="run-status" id="run-status">${busy?'正在協作…':''}</div><div class="attachments" id="attachments"></div><form id="composer" class="composer"><textarea id="prompt" rows="1" maxlength="6000" aria-label="訊息" placeholder="有什麼想一起完成的？"></textarea><div class="composer-tools"><button type="button" data-act="attachments-menu" class="icon-button" aria-label="加入來源、圖片或專案">＋</button><select id="mode" aria-label="工作模式"><option value="research">研究與規劃</option><option value="code">程式工作</option></select><select id="workflow" aria-label="Workflow"><option value="collaborative">Agent collaboration</option><option value="assisted">Assisted search · one model</option></select><select id="flow" aria-label="流程用量"><option value="minimum">最低流程 · 一次核驗 / 無 Niv</option><option value="standard">標準流程 · 一般用量</option><option value="complex">複雜流程 · 更多核驗 / 更多用量</option></select><button type="button" data-act="choose-models" class="model-pill">${selected.size?selected.size+' models':'選擇模型'} <span>⌄</span></button><span class="composer-spacer"></span><button type="button" data-act="stop" class="stop" ${busy?'':'hidden'} aria-label="停止">■</button><button class="primary send" type="submit" ${busy?'disabled':''} aria-label="傳送訊息">↑</button></div></form><p class="privacy">Naivi 也會犯錯。重要內容請查證。<span>Shift + Enter 換行</span></p></div></main><aside class="workflow" aria-label="協作流程"><div class="workflow-header"><div><span class="eyebrow">BEHIND THE ANSWER</span><h3>協作紀錄</h3></div><button class="icon-button" data-act="toggle-right" aria-label="折疊協作欄">${icon('right')}</button></div><div class="workflow-tabs"><span>${conversation.nodes.length} 個步驟</span><button data-act="view-flow">${diagram?'文字紀錄':'圖示模式'}</button></div><div class="agents">${['Phiel','Velo','Avis','Niv'].map(a=>`<div class="agent" data-agent="${a}">${orb(a)}<small>${a}</small></div>`).join('')}</div><div class="workflow-scroll"><div id="nodes"></div><p class="workflow-note">這裡顯示工作摘要、引用與執行結果。<br>每一條連線都對應實際交接的資訊。</p>${state.niv.enabled?'':'<div class="nid-off">Emotionality is actually quite important, should we open it up?<br><button data-act="niv">Niv 設定</button></div>'}</div></aside></div>`;renderMessages();revealAnswers();restoreViewport(cid,viewport);renderNodes();attachments();panels();const input=document.querySelector('#prompt');input.value=draft;document.querySelector('#flow').value=state.settings.flow||'standard';document.querySelector('#flow').onchange=async e=>{state=await call('settings',{flow:e.target.value});};document.querySelector('#mode').value=state.settings.workflow==='assisted'?'research':state.project?'code':mode;document.querySelector('#mode').disabled=!!state.project||state.settings.workflow==='assisted';const workflow=document.querySelector('#workflow');workflow.value=state.settings.workflow||'collaborative';document.querySelector('#flow').disabled=workflow.value==='assisted';workflow.onchange=async e=>{state=await call('settings',{workflow:e.target.value});if(e.target.value==='assisted'){selected=new Set([...selected].slice(0,1));if(!selected.size&&state.providers.length)selected.add(state.providers[0].id);}render();};fitInput();maybeReleaseNotice();input.oninput=()=>{draft=input.value;fitInput();};document.querySelector('#composer').onsubmit=submit;input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();submit(e);}};}
function renderMessages(){const el=document.querySelector('#messages');if(!el)return;if(!conversation.messages.length){el.innerHTML=`<div class="welcome">${fox}<span class="eyebrow">NAIVI / YOUR PERSONAL WORKSPACE</span><h1>Make room<br>for a little <em>possibility.</em></h1><p>把問題交給協作，把證據留在看得見的地方。</p><div class="prompt-buttons"><button data-act="prompt" data-text="幫我拆解一個研究問題，先列出需要確認的範圍。">從一個研究問題開始 ↗</button><button data-act="prompt" data-text="幫我規劃一個小型程式專案，列出驗收條件與風險。">把想法變成可驗收的計畫 ↗</button></div><p class="hint">從一個問題開始，也可以打開專案一起工作。</p></div>`;return;}el.innerHTML=conversation.messages.map(m=>`<article class="message ${E(m.role)}" id="message-${E(m.id)}"><div class="message-head"><input type="checkbox" data-select="${E(m.id)}" aria-label="選取此訊息以分享">${m.role==='user'?'YOU':'NAIVI'} · ${new Date(m.created).toLocaleTimeString()}${m.role==='assistant'?`<button data-act="style" data-id="${E(m.id)}">閱讀樣式</button>`:''}</div><div class="message-content">${m.role==='user'?E(m.text):answerMarkup(m)}</div>${m.meta.kind==='generated'?`<div class="message-meta">${m.meta.calls} 次模型調用 · ${Math.round(m.meta.durationMs/1000)} 秒 · ${m.meta.workflow==='assisted'?'Single model · assisted search · no Niv':m.meta.sameModelLab?'單模型角色測試，非獨立模型驗證':'多模型交叉審查'} · 事實仍需查證${usageText(m.meta.usage)}${m.meta.search?' · Tavily '+m.meta.search.credits+' credits':''}</div><details class="evidence"><summary>來源與查驗邊界 · ${m.meta.evidence?.length||0}</summary><p>Web excerpts and search snippets are labeled. A citation does not guarantee correctness. Open the source to check its context.</p>${(m.meta.evidence||[]).map(s=>`<p data-user-content>[${E(s.id)}] ${E(s.title)} · ${E(s.status)}${s.readAt?' · '+E(new Date(s.readAt).toLocaleString()):''}</p><details><summary>查看摘錄</summary><p data-user-content>${E(s.text)}</p>${s.url?`<button data-act="link" data-url="${E(s.url)}">開啟原文 ↗</button>`:''}</details>`).join('')}</details>${m.meta.proposal?.files?.length?`<button data-act="proposal" data-id="${E(m.id)}">檢視程式提案（${m.meta.proposal.files.length} 個檔案）</button>`:''}`:''}${m.meta.canContinue?'<p class="hint">Output stopped at the provider limit. Partial output is preserved.</p><button data-act="continue">Continue response →</button>':''}${m.meta.kind==='easter-egg'?'<p class="message-meta">本機彩蛋 · 0 次模型調用</p>':''}</article>`).join('');}
function nodeHtml(n){return `<details class="node" id="node-${E(n.id)}" data-state="${E(n.state)}"><summary><span class="stage-label">${E(n.agent)} / ${E(n.stage)}</span></summary><small>${E(n.provider)} · ${E(n.model)} · <span data-timer="${E(n.id)}">${Math.round((n.durationMs||Date.now()-Date.parse(n.started))/1000)}s</span> · ${E(n.state)}</small><div class="parents">${(n.parents||[]).map(id=>`<button data-act="node-link" data-id="${E(id)}">↳ ${E(id.slice(0,8))}</button>`).join('')}</div><div class="node-markdown">${markdown(n.text||(n.error?t(n.error):'Working…'))}</div></details>`;}
function renderNodes(){const el=document.querySelector('#nodes');if(!el)return;const open=new Set([...el.querySelectorAll('details[open]')].map(d=>d.id));if(diagram){const nodes=conversation.nodes,positions=new Map(nodes.map((n,i)=>[n.id,35+i*78]));el.innerHTML=`<div class="diagram"><svg viewBox="0 0 290 ${Math.max(160,nodes.length*78+50)}" role="img" aria-label="任務交接圖">${nodes.flatMap(n=>(n.parents||[]).filter(p=>positions.has(p)).map(p=>`<path d="M145 ${positions.get(p)+34} C145 ${positions.get(p)+52} 145 ${positions.get(n.id)-20} 145 ${positions.get(n.id)}"/>`)).join('')}${nodes.map(n=>`<g data-act="node-detail" data-id="${E(n.id)}" tabindex="0" role="button" aria-label="${E(n.stage)}"><rect class="${n.state==='running'?'running':''}" x="8" y="${positions.get(n.id)}" width="274" height="44" rx="6"/><text x="20" y="${positions.get(n.id)+18}">${E(n.agent)} / ${E(n.stage)}</text><text x="20" y="${positions.get(n.id)+34}" style="font-size:8px">${E(n.model)} · ${E(n.state)}</text></g>`).join('')}</svg></div>`;}else{el.innerHTML=conversation.nodes.map(nodeHtml).join('');for(const id of open)document.getElementById(id)?.setAttribute('open','');}document.querySelectorAll('[data-agent]').forEach(a=>{const own=conversation.nodes.filter(n=>n.agent===a.dataset.agent),status=own.some(n=>n.state==='running')?'thinking':own.at(-1)?.state==='error'?'failed':'rest';a.dataset.state=status;const currentRun=own.at(-1)?.runId;const start=conversation.nodes.find(n=>n.runId===currentRun)?.started;a.dataset.runStart=start?Date.parse(start):Date.now();a.classList.toggle('awake',status==='thinking');a.classList.toggle('failed',status==='failed');});syncCompanions();}
function attachments(){const el=document.querySelector('#attachments');if(el)el.textContent=[sources.length?sources.length+' 份來源':'',images.length?'圖片：'+images[0].name:'',state.project?'專案：'+state.project.files.length+' 個文字檔案':''].filter(Boolean).join(' · ');}
async function refresh(){state=await call('bootstrap');theme();}
async function load(id){if(busy&&id!==cid)throw Error('請等待目前任務完成或停止後再切換');if(cid!==id){draft='';images=[];sources=[];const input=document.querySelector('#prompt');if(input)input.value='';}cid=id;conversation=await call('conversation',{id});await refresh();mode=state.project?'code':'research';const selector=document.querySelector('#mode');if(selector)selector.value=mode;render();}
async function submit(e){e.preventDefault();if(busy)return;const input=document.querySelector('#prompt'),prompt=input.value.trim();if(!prompt)return;if(!cid){const c=await call('newConversation');cid=c.id;}try{busy=true;followOutput();await call('run',{cid,prompt,providerIds:[...selected],mode:document.querySelector('#mode').value,flow:document.querySelector('#flow').value,sources,images});input.value='';draft='';await refresh();conversation=await call('conversation',{id:cid});render();}catch(e){busy=false;toast(e.message);render();}}
function providersDialog(p=null){editingProvider=p?.id||null;showModal(settingsNav('providers')+`<h2>模型與連線</h2><p class="hint">金鑰只交給主程序，由 Windows 加密保存。中轉站會收到你傳送的內容；請自行選擇可信服務。</p>${state.providers.filter(p=>!settingsDraft.removeProviders.includes(p.id)).map(p=>`<div class="card"><strong>${E(p.name)}</strong> · ${E(p.model)}<p class="hint">${E(p.baseURL)} · ${p.vision?'支援圖片（用戶設定）':'文字'}</p><button data-act="edit-provider" data-id="${E(p.id)}">Edit</button><button data-act="test-provider" data-id="${E(p.id)}">測試連線</button> <button data-act="remove-provider" data-id="${E(p.id)}">移除</button></div>`).join('')}<label>服務名稱<input id="p-name" placeholder="DeepSeek / GPT / Claude / Gemini / 自訂中轉站"></label><div class="row"><label>協定<select id="p-protocol"><option value="openai">OpenAI-compatible Chat Completions</option><option value="anthropic">Anthropic Messages</option></select></label><label>模型 ID<input id="p-model" placeholder="請填服務商提供的型號"></label></div><label>API 基底位址<input id="p-base" placeholder="https://api.deepseek.com 或 https://api.example.com/v1"></label><label>API Key<input id="p-key" type="password" autocomplete="off" spellcheck="false"></label><label><input type="checkbox" id="p-vision"> 此模型／端點支援圖片（依服務商文件確認）</label><label>Provider maximum output (Anthropic protocol)<input id="p-capacity" type="number" min="1" placeholder="Use the maximum supported by this model"></label><button class="primary" data-act="save-provider">Save model</button><p class="hint">系統依任務自動分派已選模型：研究優先 DeepSeek；程式起草優先 GPT／Codex；審查優先 Claude；圖片使用支援視覺的模型。缺少時選擇可用模型，所有實際分派顯示於協作紀錄。這是路由規則，不是品質保證。</p><footer class="settings-save"><span>Changes apply only after saving.</span><button class="primary" data-act="save-appearance">儲存設定</button></footer>`);if(p){for(const [id,value]of Object.entries({'p-name':p.name,'p-model':p.model,'p-base':p.baseURL,'p-protocol':p.protocol,'p-capacity':p.outputCapacity||''}))document.getElementById(id).value=value;document.querySelector('#p-vision').checked=!!p.vision;}}
function nivDialog(){settingsNav('niv');const niv=settingsDraft.niv;showModal(settingsNav('niv')+`<h2>Niv — Your preferences.</h2><p>Phiel 篩選你明確提供的一般資料與偏好，交給 Niv 保存。Niv 選擇相關記憶與章節權重，最後由 Phiel 調整答案的詳略與表達；其他分析階段不讀取記憶。</p><label><input id="niv-enabled" type="checkbox" ${niv.enabled?'checked':''}> 啟用 Niv</label><label><input id="niv-auto" type="checkbox" ${niv.automatic!==false?'checked':''}> 自動記憶偏好</label><label>偏好主題（每行「主題 | 權重 1–5」）<textarea id="niv-topics">${E(niv.topics.map(t=>t.name+' | '+t.weight).join('\n'))}</textarea></label><p class="hint">啟用後每輪增加記憶篩選、相關性整理及必要的個人化模型調用。僅從你本輪明確提供的內容抽取資料；候選記憶須有原文依據並經本機過濾。記憶存於本機，相關項目會交給設定的模型服務。你可以修改、清除或關閉。</p><button data-act="clear-niv">清除記憶</button><footer class="settings-save"><span>Changes apply only after saving.</span><button class="primary" data-act="save-niv">儲存設定</button></footer>`);}
function wikiDialog(){showModal(`<h2>CodeWiki / Timeline</h2><p class="hint">生成、提案、套用、實際測試與回滾分開記錄。</p>${conversation.wiki.map(w=>`<article class="card"><span class="eyebrow">${E(w.created)} · ${E(w.type)}</span><h3>${E(w.state)}</h3>${w.changes?`<p>${w.changes.map(c=>E(c.path)).join('<br>')}</p>`:''}<details><summary>完整紀錄</summary><pre>${E(JSON.stringify(w,null,2))}</pre></details>${w.state==='applied'?`<button data-act="test-code" data-id="${E(w.id)}">執行 Node 測試</button> <button data-act="rollback" data-id="${E(w.id)}">回滾檔案</button>`:''}</article>`).join('')||'<p>還沒有程式任務。</p>'}`);}
function shareDialog(){const ids=[...document.querySelectorAll('[data-select]:checked')].map(c=>c.dataset.select);if(!ids.length)throw Error('請先勾選要分享的訊息');const messages=conversation.messages.filter(m=>ids.includes(m.id));showModal(`<h2>Share deliberately.</h2><p>以下內容將建立獨立的 24 小時 Snap。可在「我的 Snap」立即銷毀。</p><pre>${E(messages.map(m=>m.role+':\n'+m.text).join('\n\n')).slice(0,80000)}</pre>${messages.length===1&&messages[0].meta.kind==='generated'?'<label>只分享其中一段（可留空；需為原文片段）<textarea id="share-excerpt"></textarea></label>':''}<button class="primary" data-act="confirm-share" data-ids="${E(ids.join(','))}">確認分享內容 →</button>`);}
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('g[data-act]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('click',event=>{const a=event.target.closest('.section-nav a');if(a){event.preventDefault();document.getElementById(a.getAttribute('href').slice(1))?.scrollIntoView({block:'start'});}});
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',theme);
document.addEventListener('click',async event=>{const button=event.target.closest('[data-act]');if(!button)return;const action=button.dataset.act;try{
 if(action==='copy-code'){event.preventDefault();event.stopPropagation();await call('copyText',{text:button.closest('.code-block').querySelector('code').textContent});toast('Copied.');return;}
 if(action==='release-search'){modal.close();settingsDialog('search');return;}if(action==='release-later'){modal.close();return;}if(action==='test-search'){button.disabled=true;try{const result=await call('testSearch');toast('Search connected: '+result.sources+' sources · '+result.credits+' credits');}finally{button.disabled=false;}return;}
 if(action==='privacy-settings'){modal.close();consent();}
 else if(action==='remote'){const tasks=await call('remoteList');showModal(`<h2>Remote tasks.</h2><p>Keep this computer awake and Naivi running. Create a separate 72-hour link and save its KEY yourself. Keys are shown only once.</p><button class="primary" data-act="remote-create" ${state.user?.guest?'disabled':''}>Create a remote task</button>${tasks.map(t=>`<article class="card"><p>${E(t.url)}</p><p>${new Date(t.expiresAt).toLocaleString()} · ${t.revoked?'Revoked':'Active'}</p><button data-act="link" data-url="${E(t.url)}">Open ↗</button><button data-act="remote-revoke" data-id="${E(t.id)}" ${t.revoked?'disabled':''}>Revoke now</button></article>`).join('')}<p class="hint">Sign in to use remote tasks. Project file changes are applied automatically after the local authorization. Use /terminal followed by a command for explicit terminal execution.</p>`);}
 else if(action==='remote-create'){button.disabled=true;try{const t=await call('remoteCreate',{providers:[...selected]});if(t)showModal(`<h2>Save your KEY.</h2><p>${E(t.url)}</p><label>KEY<input readonly value="${E(t.key)}" spellcheck="false"></label><p>Save this KEY separately from the link. It cannot be recovered from the website.</p><p>Expires: ${new Date(t.expiresAt).toLocaleString()}</p>`);}finally{button.disabled=false;}}
 else if(action==='remote-revoke'){await call('remoteRevoke',{id:button.dataset.id});modal.close();toast('Remote task revoked.');}
 else if(action==='consent'){state=await call('consent',{language:document.querySelector('#language').value,optional:button.dataset.optional==='true'});render();}
 else if(action==='guest'){state=await call('guest');selected=new Set(state.providers.map(p=>p.id));render();}
 else if(action==='open-project')await call('openProject',{editor:button.dataset.editor==='true'});
 else if(action==='settings')settingsDialog();
 else if(action==='settings-tab'){captureSettings();settingsDialog(button.dataset.tab);}
 else if(action==='css-manual')await call('openCSSManual');
 else if(action==='project-panel')await projectDialog();
 else if(action==='new-project')showModal('<h2>建立專案</h2><label>專案名稱<input id="project-name" maxlength="70" placeholder="My project"></label><button class="primary" data-act="create-project">選擇位置並建立</button>');
 else if(action==='general-chat'){await call('clearProject');await refresh();const c=await call('newConversation');modal.close();await load(c.id);}
 else if(action==='create-project'){const p=await call('createProject',{name:document.querySelector('#project-name').value});if(p){await refresh();const c=await call('newConversation');await load(c.id);await projectDialog();}}
 else if(action==='edit-file')fileEditor(await call('readFile',{path:button.dataset.path}));
 else if(action==='new-file')fileEditor();
 else if(action==='new-folder')showModal('<h2>建立資料夾</h2><label>相對路徑<input id="folder-path" placeholder="src"></label><button class="primary" data-act="create-folder">建立</button>');
 else if(action==='create-folder'){if(await call('createFolder',{path:document.querySelector('#folder-path').value}))await projectDialog();}
 else if(action==='save-file'){button.disabled=true;try{const r=await call('saveFile',{cid,path:document.querySelector('#file-path').value,text:document.querySelector('#file-text').value});if(r){state.project=r.project;if(!cid)cid=r.record.cid;await refresh();conversation=await call('conversation',{id:cid});render();await projectDialog();toast('已寫入電腦，回滾快照保存在 CodeWiki。');}}finally{button.disabled=false;}}
 else if(action==='feedback')await call('openFeedback');
 else if(action==='toggle-left'||action==='toggle-right'){const key=action==='toggle-left'?'leftCollapsed':'rightCollapsed';state.settings[key]=!state.settings[key];panels();await call('settings',{[key]:state.settings[key]});setTimeout(fitInput,420);}
 else if(action==='chat-menu')showModal(`<h2>對話選項</h2><div class="settings-actions"><button data-act="export">匯出 Markdown</button><button data-act="snaps">我的 Snap</button><button data-act="delete">刪除此對話</button></div>`);
 else if(action==='attachments-menu')showModal(`<h2>帶上你的材料</h2><div class="settings-actions"><button data-act="sources">加入來源摘錄</button><button data-act="image">選擇圖片</button><button data-act="project">選擇專案資料夾</button><button data-act="clear-attachments">清除附件</button></div>`);
 else if(action==='clear-attachments'){images=[];sources=[];await call('clearProject');state.project=null;attachments();modal.close();}
 else if(action==='manual')await call('openManual');
 else if(action==='accept'){if(!document.querySelector('#agree').checked)throw Error('請閱讀並勾選同意');state=await call('acceptTerms',{version:state.termsVersion,accept:true});render();}
 else if(action==='send-code'){button.disabled=true;try{await call('sendCode',{email:document.querySelector('#email').value,penName:document.querySelector('#penName').value});sessionStorage.setItem('otp-until',String(Date.now()+60000));toast('驗證碼已寄出，請查看信箱。');}finally{startCooldown(button);}}
 else if(action==='login'){button.disabled=true;try{state=await call('login',{email:document.querySelector('#email').value,code:document.querySelector('#otp').value});selected=new Set(state.providers.map(p=>p.id));render();}finally{button.disabled=false;}}
 else if(action==='logout'){state=await call('logout');cid=null;conversation={messages:[],nodes:[],wiki:[]};render();}
 else if(action==='new'){if(busy)throw Error('請先停止任務');if(emptyChat())return;draft='';const c=await call('newConversation');await refresh();await load(c.id);}
 else if(action==='load')await load(button.dataset.id);
 else if(action==='prompt'){document.querySelector('#prompt').value=t(button.dataset.text);document.querySelector('#prompt').focus();}
 else if(action==='providers')providersDialog();
 else if(action==='edit-provider')providersDialog(state.providers.find(p=>p.id===button.dataset.id));
 else if(action==='save-provider')await saveSettings();
 else if(action==='test-provider'){button.disabled=true;try{const result=await call('testProvider',{id:button.dataset.id});toast('連線成功：'+result.slice(0,80));}finally{button.disabled=false;}}
 else if(action==='remove-provider'){settingsDraft.removeProviders.push(button.dataset.id);providersDialog();}
 else if(action==='choose-models')showModal(`<h2>本次協作模型</h2>${state.providers.map(p=>`<label><input data-provider="${E(p.id)}" type="checkbox" ${selected.has(p.id)?'checked':''}> ${E(p.name)} / ${E(p.model)}</label>`).join('')||'<p>請先加入模型。</p>'}<button class="primary" data-act="set-models">確認</button>`);
 else if(action==='set-models'){if(state.settings.workflow==='assisted'&&document.querySelectorAll('[data-provider]:checked').length!==1)throw Error('Assisted search requires exactly one selected model.');selected=new Set([...document.querySelectorAll('[data-provider]:checked')].map(e=>e.dataset.provider));modal.close();render();}
 else if(action==='appearance')appearanceDialog();
 else if(action==='save-appearance'||action==='save-niv')await saveSettings();
 else if(action==='niv')nivDialog();
 else if(action==='clear-niv'){captureSettings();settingsDraft.niv.topics=[];settingsDraft.nivChanged=true;nivDialog();}
 else if(action==='sources')showModal(`<h2>提供可查驗的來源</h2><p class="hint">摘錄會傳給模型；來源文字不會獲得工具權限。Alpha 不會自動聲稱已瀏覽原網站。</p>${sources.map((s,i)=>`<div class="card">[S${i+1}] ${E(s.title)} <button data-act="remove-source" data-id="${i}">移除</button></div>`).join('')}<label>標題<input id="source-title" maxlength="150"></label><label>原文 HTTPS 連結（可選）<input id="source-url"></label><label>原文摘錄<textarea id="source-text" maxlength="12000"></textarea></label><button class="primary" data-act="add-source">加入來源</button>`);
 else if(action==='add-source'){if(sources.length>=6)throw Error('最多六份來源');const text=document.querySelector('#source-text').value;if(!text.trim())throw Error('請貼上原文摘錄');sources.push({title:document.querySelector('#source-title').value,url:document.querySelector('#source-url').value,text});modal.close();attachments();}
 else if(action==='remove-source'){sources.splice(Number(button.dataset.id),1);modal.close();attachments();}
 else if(action==='image'){modal.close();const img=await call('image');if(img){images=[img];attachments();}}
 else if(action==='project'){modal.close();const p=await call('project');if(p){await refresh();const c=await call('newConversation');await load(c.id);}}
 else if(action==='stop')await call('stop');
 else if(action==='view-flow'){diagram=!diagram;button.textContent=diagram?'文字':'圖示';renderNodes();}
 else if(action==='node-link'){const n=document.getElementById('node-'+button.dataset.id);if(n){n.open=true;n.scrollIntoView({block:'center'});}}
 else if(action==='node-detail'){const n=conversation.nodes.find(n=>n.id===button.dataset.id);showModal(`<h2>${E(n.stage)}</h2>${nodeHtml(n)}`);modalBody.querySelector('details').open=true;}
 else if(action==='context-rename'){showModal(`<h2>Rename conversation</h2><input id="chat-title" maxlength="80" value="${E(state.conversations.find(c=>c.id===button.dataset.id)?.title||'')}"><button data-act="rename-chat" data-id="${E(button.dataset.id)}">Save</button>`);}
 else if(action==='rename-chat'){state=await call('renameConversation',{id:button.dataset.id,title:document.querySelector('#chat-title').value});modal.close();render();}
 else if(action==='context-delete'){state=await call('deleteConversation',{id:button.dataset.id});if(!state.conversations.some(c=>c.id===cid)){cid=null;conversation={messages:[],nodes:[],wiki:[]};}modal.close();render();}
 else if(action==='context-export'){await call('export',{cid:button.dataset.id});}
 else if(action==='context-share'){const c=await call('conversation',{id:button.dataset.id});const result=await call('share',{cid:button.dataset.id,ids:c.messages.slice(-20).map(m=>m.id)});if(result)showModal(`<h2>Snap ready.</h2><p>${E(result.url)}</p><button data-act="link" data-url="${E(result.url)}">Open ↗</button>`);}
 else if(action==='continue'){document.querySelector('#prompt').value='Continue the previous incomplete response from where it stopped. Do not repeat the completed part.';await submit(event);}
 else if(action==='delete'){if(!cid)return;state=await call('deleteConversation',{id:cid});if(!state.conversations.some(c=>c.id===cid)){cid=null;conversation={messages:[],nodes:[],wiki:[]};}render();}
 else if(action==='export'){if(!cid)throw Error('沒有可匯出的對話');if(await call('export',{cid}))toast('已匯出 Markdown');}
 else if(action==='wiki'){if(cid)conversation=await call('conversation',{id:cid});wikiDialog();}
 else if(action==='proposal'){const m=conversation.messages.find(m=>m.id===button.dataset.id);showModal(`<h2>Review before changing.</h2><p>${E(m.meta.proposal.summary)}</p>${m.meta.proposal.files.map(f=>`<h3>${E(f.path)}</h3><pre>${E(f.content)}</pre>`).join('')}<button class="primary" data-act="apply" data-id="${E(m.id)}">確認套用這份提案</button>`);}
 else if(action==='apply'){const result=await call('apply',{cid,messageId:button.dataset.id});if(result){conversation=await call('conversation',{id:cid});wikiDialog();toast('已套用並保存回滾快照。');}}
 else if(action==='rollback'||action==='test-code'){button.disabled=true;try{await call(action==='test-code'?'testCode':'rollback',{cid,id:button.dataset.id});conversation=await call('conversation',{id:cid});wikiDialog();}finally{button.disabled=false;}}
 else if(action==='share')shareDialog();
 else if(action==='confirm-share'){button.disabled=true;try{const result=await call('share',{cid,ids:button.dataset.ids.split(','),excerpt:document.querySelector('#share-excerpt')?.value||''});if(result){await refresh();showModal(`<h2>Snap ready.</h2><p>${E(result.url)}</p><p>到期：${E(result.expiresAt)}</p><button data-act="link" data-url="${E(result.url)}">開啟分享 ↗</button>`);}}finally{button.disabled=false;}}
 else if(action==='snaps'){await refresh();showModal(`<h2>我的 Snap</h2>${state.snaps.map(s=>`<div class="card"><p>${E(s.url)}</p><p class="hint">${s.revoked?'已銷毀':'到期 '+E(s.expiresAt)}</p><button data-act="link" data-url="${E(s.url)}">開啟</button> <button data-act="revoke" data-id="${E(s.slug)}" ${s.revoked?'disabled':''}>立即銷毀</button></div>`).join('')||'<p>尚未分享。</p>'}`);}
 else if(action==='revoke'){const next=await call('revoke',{slug:button.dataset.id});if(next){state=next;modal.close();toast('Snap 已銷毀。');}}
 else if(action==='link')await call('openLink',{url:button.dataset.url});
 else if(action==='style'){const m=conversation.messages.find(m=>m.id===button.dataset.id);showModal(`<h2>DICK / Reading study</h2><p class="hint">這是隔離的閱讀預覽，CSS 無法存取網路、金鑰或桌面工具。原始回答不會被改寫。</p><label>自訂 CSS<textarea id="custom-css" spellcheck="false">body { font-family: Georgia, serif; color: #292d35; line-height: 1.9; padding: 24px; } h2 { border-bottom: 1px solid #aaa; padding-bottom: 10px; } blockquote { border-left: 3px solid #596d8b; padding-left: 16px; }</textarea></label><button data-act="preview-style" data-id="${E(m.id)}">預覽</button><iframe sandbox="" id="style-preview" title="隔離閱讀預覽"></iframe>`);}
 else if(action==='preview-style'){const m=conversation.messages.find(m=>m.id===button.dataset.id),css=document.querySelector('#custom-css').value.slice(0,12000).replace(/</g,'\\3c ');document.querySelector('#style-preview').srcdoc=`<!doctype html><html><head><meta http-equiv="Content-Security-Policy" content="default-src 'none';style-src 'unsafe-inline';base-uri 'none';form-action 'none'"><style>${css}</style></head><body>${markdown(m.text)}</body></html>`;}
 }catch(e){toast(e.message);}});
window.naivi.events(async event=>{if(event.cid!==cid)return;if(event.type==='node'){const i=conversation.nodes.findIndex(n=>n.id===event.node.id);if(i<0)conversation.nodes.push(event.node);else conversation.nodes[i]=event.node;renderNodes();const status=document.querySelector('#run-status');if(status)status.textContent=event.node.agent+' / '+event.node.stage+' · '+event.node.state;}else if(event.type==='delta'){const n=conversation.nodes.find(n=>n.id===event.id);if(n){n.text+=event.text;const el=document.querySelector('#node-'+n.id+' .node-markdown');if(el)el.innerHTML=markdown(n.text);}}else if(event.type==='answer'||event.type==='idle'){if(event.type==='answer'&&event.message?.id)reveals.set(event.message.id,Date.now());if(event.type==='idle')busy=false;await refresh();conversation=await call('conversation',{id:cid});render();}else if(event.type==='failed')toast(event.message);});
setInterval(()=>{if(document.hidden||!busy)return;document.querySelectorAll('[data-timer]').forEach(el=>{const n=conversation.nodes.find(n=>n.id===el.dataset.timer);if(n?.state==='running')el.textContent=Math.floor((Date.now()-Date.parse(n.started))/1000)+'s';});},1000);
try{state=await call('bootstrap');selected=new Set(state.providers?.map(p=>p.id)||[]);if(state.conversations?.length){cid=state.conversations[0].id;conversation=await call('conversation',{id:cid});await refresh();mode=state.project?'code':'research';}render();}catch(e){root.textContent='Naivi 啟動失敗：'+e.message;}

document.addEventListener('keydown',async e=>{if(e.ctrlKey&&e.shiftKey&&e.key==='Backspace'){e.preventDefault();try{state=await call('settings',{customCSS:''});theme();toast('已停用自訂 CSS');}catch{}}if(e.ctrlKey&&e.key.toLowerCase()==='n'){e.preventDefault();document.querySelector('[data-act=new]:not(:disabled)')?.click();}});

window.addEventListener('resize',fitInput);

function orb(agent){return '<span class="agent-orb" aria-hidden="true"><span class="orb-wait" title="角色等待動畫，不代表模型故障"></span><span class="orb-eyes"><i></i><i></i></span></span>';}
function startCooldown(button){if(!button)return;const tick=()=>{const n=Math.max(0,Math.ceil((Math.max(Number(sessionStorage.getItem('otp-until')),state.settings?.otpUntil||0)-Date.now())/1000)||0);button.disabled=n>0;button.textContent=n?'重新寄送（'+n+'s）':'寄送驗證碼';if(n&&button.isConnected)setTimeout(tick,250);};tick();}
let pointerFrame=0;document.addEventListener('pointermove',e=>{if(pointerFrame)return;const x=e.clientX,y=e.clientY;pointerFrame=requestAnimationFrame(()=>{pointerFrame=0;document.querySelectorAll('.agent[data-state=thinking]:not(.daydreaming) .agent-orb').forEach(o=>{const r=o.getBoundingClientRect();o.style.setProperty('--eye-x',Math.max(-4,Math.min(4,(x-r.x-r.width/2)/70))+'px');o.style.setProperty('--eye-y',Math.max(-3,Math.min(3,(y-r.y-r.height/2)/90))+'px');});});});

function syncLanguage(){const select=document.querySelector('#language');if(select)select.value=state.settings?.language||'zh-Hant';}
document.addEventListener('change',async e=>{if(e.target.id!=='language')return;if(settingsDraft&&modal.open){settingsDraft.appearance.language=e.target.value;return;}try{state=await call('language',{language:e.target.value});setLanguage(state.settings.language);}catch(error){toast(error.message);}});
function revealAnswers(){for(const [id,start] of reveals){const el=document.querySelector('#message-'+id+' .message-content');if(!el)continue;const age=Date.now()-start;if(age>3500||matchMedia('(prefers-reduced-motion:reduce)').matches||document.body.classList.contains('no-effects')){reveals.delete(id);continue;}const lines=Math.max(1,Math.ceil(el.scrollHeight/(parseFloat(getComputedStyle(el).lineHeight)||24))),duration=Math.min(3000,lines*65);const animation=el.animate([{height:'0px',overflow:'hidden'},{height:el.scrollHeight+'px',overflow:'hidden'}],{duration,easing:'steps('+lines+', end)',fill:'both'});animation.currentTime=Math.min(age,duration);animation.onfinish=()=>{animation.cancel();reveals.delete(id);};}}

document.addEventListener('contextmenu',e=>{const b=e.target.closest('.conversation');if(!b)return;e.preventDefault();showModal(`<span class="eyebrow">CONVERSATION</span><h2>${E(state.conversations.find(c=>c.id===b.dataset.id)?.title||'')}</h2><div class="context-actions">${[['context-share','Share as a 24h Snap'],['context-rename','Rename'],['context-export','Export Markdown'],['context-delete','Delete']].map(([act,label])=>`<button data-act="${act}" data-id="${E(b.dataset.id)}">${label} ↗</button>`).join('')}</div>`);});
document.addEventListener('keydown',e=>{if(e.shiftKey&&e.key==='F10'&&e.target.matches('.conversation')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true}));}});

function previewReading(){
 const size=document.querySelector('#font-size')?.value;if(!size)return;
 document.querySelector('#font-value').textContent=size;
 const en={serif:'Georgia',sans:'Inter',mono:'Consolas'},zh={sans:'"Microsoft JhengHei","PingFang TC","Noto Sans TC"',serif:'"Noto Serif TC","PMingLiU"'};
 const preview=document.querySelector('.font-specimen');preview.style.setProperty('--preview-size',size+'px');preview.style.setProperty('--preview-font',`${en[document.querySelector('#font-en').value]},${zh[document.querySelector('#font-zh').value]},sans-serif`);
}
function captureSettings(){
 if(!settingsDraft)return;
 const value=id=>document.getElementById(id).value,checked=id=>document.getElementById(id).checked;
 if(document.querySelector('#font-size'))Object.assign(settingsDraft.appearance,{language:value('language'),layout:value('layout'),outputLimit:value('limit-mode')==='custom'?Number(value('output-limit')):null,theme:value('theme'),accent:value('accent'),effects:checked('effects'),showAgents:checked('show-agents'),allowSameModel:checked('same-model'),fontSize:Number(value('font-size')),fontEn:value('font-en'),fontZh:value('font-zh'),customCSS:value('app-css')});
 if(document.querySelector('#p-name')&&['p-name','p-model','p-base','p-key'].some(id=>value(id).trim()))settingsDraft.provider={id:editingProvider,name:value('p-name'),model:value('p-model'),baseURL:value('p-base'),key:value('p-key'),protocol:value('p-protocol'),outputCapacity:Number(value('p-capacity'))||undefined,vision:checked('p-vision')};
 if(document.querySelector('#search-mode'))Object.assign(settingsDraft.appearance,{searchMode:value('search-mode'),searchQueries:Number(value('search-queries')),searchCredits:Number(value('search-credits'))});
 if(document.querySelector('#search-key')?.value)settingsDraft.appearance.searchKey=value('search-key');
 if(document.querySelector('#remove-search-key')?.checked)settingsDraft.appearance.removeSearchKey=true;
 if(document.querySelector('#niv-topics')){settingsDraft.nivChanged=true;settingsDraft.niv={enabled:checked('niv-enabled'),automatic:checked('niv-auto'),topics:value('niv-topics').split('\n').map(line=>{const [name,weight]=line.split('|');return {name:name.trim(),weight:Number(weight)||1};}).filter(t=>t.name)};}
}
async function saveSettings(){
 captureSettings();if(!settingsDraft)return;const pending=settingsDraft;if(busy&&(pending.nivChanged||pending.removeProviders.length))throw Error('Wait for the current task to finish.');
 if(pending.appearance.outputLimit!==null&&pending.appearance.outputLimit!==undefined&&(!Number.isSafeInteger(pending.appearance.outputLimit)||pending.appearance.outputLimit<1))throw Error('Output limit must be a positive integer, or unlimited.');
 if(pending.provider)state=await call('saveProvider',pending.provider);
 state=await call('settings',pending.appearance);
 for(const id of pending.removeProviders){state=await call('removeProvider',{id});selected.delete(id);}
 if(pending.nivChanged)state=await call('niv',pending.niv);
 modal.close();render();toast('Settings saved.');
}

function usageText(u){return u&&u.reportedCalls?' · '+(u.input+u.output).toLocaleString()+' tokens'+(u.complete?'':' (partial usage)'):'';}
function searchDialog(){settingsNav('search');const s=settingsDraft.appearance;showModal(settingsNav('search')+`<span class="eyebrow">THE WEB, WITH SOURCES</span><h2>Search on your terms.</h2><p>Use your own Tavily account. Your public search terms are sent to Tavily; selected excerpts are sent to your model. Private project files and stored Niv memory are not included in search planning.</p><button data-act="link" data-url="https://app.tavily.com">Get a Tavily API key ↗</button><label>Tavily API Key<input id="search-key" type="password" autocomplete="off" spellcheck="false" placeholder="${state.search?.configured?'Saved securely. Leave blank to keep.':'Enter your own Tavily key'}"></label>${state.search?.configured?'<label><input id="remove-search-key" type="checkbox"> Remove saved search key</label>':''}<label>Search in agent collaboration<select id="search-mode"><option value="off">Off</option><option value="auto">Auto · search when needed</option><option value="on">On · always search</option></select></label><div class="row"><label>Maximum queries per answer<input id="search-queries" type="number" min="1" max="4" value="${s.searchQueries||2}"></label><label>Maximum search credits per answer<input id="search-credits" type="number" min="1" max="10" value="${s.searchCredits||4}"></label></div><div class="tip-box"><strong>Assisted search</strong><p>Select Assisted search below the composer, then choose exactly one model. It creates search terms, reads Tavily results and answers. No other agents, reviews, Niv or project edits participate.</p></div><p class="hint">Tavily is billed separately from your model. A basic search costs credits; page extraction can use additional credits. Set account spending limits with Tavily. Naivi has no bundled studio search key.</p><button data-act="test-search" ${state.search?.configured?'':'disabled'}>Test saved connection</button><p class="hint">Save a new key before testing. This test makes a real search request.</p><footer class="settings-save"><span>Changes apply only after saving.</span><button class="primary" data-act="save-appearance">儲存設定</button></footer>`);document.querySelector('#search-mode').value=s.searchMode||'off';}
function usageDialog(){const u=state.usage||{};showModal(settingsNav('usage')+`<span class="eyebrow">PROVIDER-REPORTED USAGE</span><h2>Know what you use.</h2><div class="usage-grid"><article><strong>${(u.input||0).toLocaleString()}</strong><span>Input tokens</span></article><article><strong>${(u.output||0).toLocaleString()}</strong><span>Output tokens</span></article><article><strong>${(u.cached||0).toLocaleString()}</strong><span>Cached input tokens</span></article></div><p>Coverage: ${u.reportedCalls||0} / ${u.modelCalls||0} model calls. ${u.complete?'All recorded model calls reported usage.':'Some providers did not report usage. These totals are incomplete.'}</p><p class="hint">Totals cover conversations retained in this local profile. Cached tokens are a subset of input tokens. Search credits are separate. Token counts do not directly equal your provider invoice.</p>`);}
function maybeReleaseNotice(){if(state.version!=='4.0.1'||state.settings.releaseSeen401||modal.open)return;state.settings.releaseSeen401=true;showModal(`<section class="release-note"><span class="eyebrow">SANGUAI INC. HK. & CYGNUS AUTOMATION</span><span class="release-version">WHAT’S NEW / 4.0.1</span><h2>A little more<br>connected.</h2><p>Naivi can now search the web, read source excerpts and bring citations into your answers.</p><div class="release-steps"><article><b>01</b><div><strong>Bring your Tavily key.</strong><p>Start with your own Tavily developer account, then save its key in Settings → Search. Try its free developer credits and upgrade if needed; current quotas are set by Tavily. Search and model usage are billed separately.</p></div></article><article><b>02</b><div><strong>Choose your workflow.</strong><p>Assisted search uses one model: plan → Tavily → answer. Agent collaboration can search automatically while retaining reviews and optional Niv.</p></div></article><article><b>03</b><div><strong>Keep the evidence close.</strong><p>Open source cards, check excerpts and set a search credit budget. Web pages cannot authorize computer operations.</p></div></article></div><div class="settings-actions"><button class="primary" data-act="release-search">Set up search →</button><button data-act="release-later">Explore first</button></div><p class="hint">Shown once on this installation profile. Find these options again in Settings.</p></section>`);modal.classList.add('release-dialog');call('seenRelease').catch(e=>toast(e.message));}
